import {Container} from "@/components/shared/Container/Container";
import Image, {getImageProps} from "next/image";
import {Link} from "@/i18n/navigation";
import {Icon} from "@/components/shared/Icon";
import type {HomeContent} from "./types";
import {homeImages, homeServices} from "@/content/home";
import styles from "./HomeServices.module.css";
import common from "./HomeCommon.module.css";

type HomeServicesBlockProps = {
    content: HomeContent["services"];
    label: string;
};

export function HomeServicesBlock({content, label}: HomeServicesBlockProps) {
  const mobileWeddingImage = getImageProps({src: homeImages.events, alt: content.weddings.alt, fill: true, sizes: "calc(100vw - 40px)"}).props;
  const serviceImageSizes = "(min-width: 1440px) 411px, (min-width: 1200px) calc((100vw - 208px) / 3), (min-width: 600px) calc((100vw - 88px) / 2), calc(100vw - 40px)";
  return (
    <Container as="section" className={styles.services} aria-label={label}>
      {homeServices.map((service) => {
        const item = content[service.id];
        return (
          <Link key={service.id} href={service.href} className={`${styles.service} ${styles[service.id] ?? ""}`}>
            <picture className={styles.servicePhoto}>
              {service.id === "weddings" && <source media="(max-width: 599px)" srcSet={mobileWeddingImage.srcSet} sizes={mobileWeddingImage.sizes} />}
              <Image src={service.image} alt={item.alt} fill sizes={service.id === "weddings" ? "(min-width: 1200px) 33vw, (min-width: 600px) calc(100vw - 64px), calc(100vw - 40px)" : serviceImageSizes} className={common.cover} />
            </picture>
            <div className={styles.serviceFade} aria-hidden="true" />
            <div className={styles.serviceCaption}>
              <div><h2>{item.title}</h2><p>{item.description}</p></div>
              <span className={styles.serviceArrow}><Icon name="arrow-up-right" /></span>
            </div>
          </Link>
        );
      })}
    </Container>
  );
}
